// Ablage-Zeilen → Cockpit-Vertrag. Verarbeitet alle gelesenen Zeilen, filtert optional auf objektId.
const anfrage = $('Datenraum-Status abrufen').first().json;
const filterId = anfrage.query?.objektId ?? null;
const zeilen = $input.all().map((i) => i.json).filter((z) => z && (z.objektId || z.objektName));
const objekte = zeilen
  .filter((z) => !filterId || z.objektId === filterId || z.objektName === filterId)
  .map((z) => ({
    objektId: z.objektId ?? null,
    objektName: z.objektName ?? null,
    stand: z.stand ?? null,
    dokumente: Array.isArray(z.dokumente) ? z.dokumente : JSON.parse(z.dokumente ?? '[]'),
    kennwerte: Array.isArray(z.kennwerte) ? z.kennwerte : JSON.parse(z.kennwerte ?? '[]'),
    freigaben: Array.isArray(z.freigaben) ? z.freigaben : JSON.parse(z.freigaben ?? '[]'),
  }));
const stand = objekte.map((o) => o.stand).filter(Boolean).sort().pop() ?? new Date().toISOString();
return [{ json: { stand, anzahl: objekte.length, objekte } }];

// Lauf-Liste der Engine in einzelne Elemente auftrennen.
const roh = $input.first().json;
const laeufe = Array.isArray(roh.laeufe) ? roh.laeufe : [];
if (laeufe.length === 0) return [];
return laeufe.map((lauf) => ({ json: { lauf } }));

// Lauf-Übersicht von Modul 01 auf den Cockpit-Vertrag abbilden.
// Die Engine liefert Prüffälle (eintraege) und Kennzahlen (kpi), keine
// vollständige Dokumentliste. Entsprechend werden nur Prüffälle als
// Dokumente gemeldet; die Mengen stehen in den Kennwerten.
const jetzt = new Date().toISOString();
return $input.all().map((i) => {
  const u = i.json ?? {};
  const eintraege = Array.isArray(u.eintraege) ? u.eintraege : [];
  const dokumente = eintraege.map((e) => ({
    name: e.anzeige ?? e.datei ?? 'unbenannt',
    status: e.art === 'review' ? 'in_pruefung' : 'unklar',
  }));
  const k = u.kpi ?? null;
  const kennwerte = k === null ? [] : [
    { feld: 'verarbeitet', wert: String(k.verarbeitet ?? 0), quelle: 'Modul 01' },
    { feld: 'abgelegt', wert: String(k.abgelegt ?? 0), quelle: 'Modul 01' },
    { feld: 'zu bestätigen', wert: String(k.qc ?? 0), quelle: 'Modul 01' },
    { feld: 'in Prüfung', wert: String(k.review ?? 0), quelle: 'Modul 01' },
    { feld: 'Duplikate', wert: String(k.duplikate ?? 0), quelle: 'Modul 01' },
    { feld: 'offen', wert: String(k.offen ?? 0), quelle: 'Modul 01', pruefstatus: 'pruefen' },
  ];
  return { json: { objektId: null, objektName: u.lauf ?? null, stand: jetzt,
                   dokumente, kennwerte, freigaben: [] } };
});
